import Foundation

class RateLimiter {
    private var tokens: Int
    private let maxTokens: Int
    private let refillRate: TimeInterval
    private var lastRefill: Date
    private let lock = NSLock()

    init(maxTokens: Int = 100, refillRate: TimeInterval = 1.0) {
        self.maxTokens = maxTokens
        self.tokens = maxTokens
        self.refillRate = refillRate
        self.lastRefill = Date()
    }

    func tryConsume() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        refillTokens()
        if tokens > 0 {
            tokens -= 1
            return true
        }
        return false
    }

    private func refillTokens() {
        let now = Date()
        let elapsed = now.timeIntervalSince(lastRefill)
        let newTokens = Int(elapsed / refillRate)
        if newTokens > 0 {
            tokens = min(maxTokens, tokens + newTokens)
            lastRefill = now
        }
    }
}

class RetryPolicy {
    let maxRetries: Int
    let baseDelay: TimeInterval

    init(maxRetries: Int = 3, baseDelay: TimeInterval = 0.5) {
        self.maxRetries = maxRetries
        self.baseDelay = baseDelay
    }

    func delay(forAttempt attempt: Int) -> TimeInterval {
        return baseDelay * pow(2.0, Double(attempt))
    }
}

struct ProxyConfig {
    let allowedHosts: [String]
    let dnsResolver: String
    let logDirectory: String
    let enableDiagnostics: Bool

    func isHostAllowed(_ host: String) -> Bool {
        return allowedHosts.contains(where: { host.hasSuffix($0) })
    }
}

class NetworkProxy {
    private let rateLimiter: RateLimiter
    private let retryPolicy: RetryPolicy
    private let config: ProxyConfig
    private let session: URLSession

    init(config: ProxyConfig, rateLimiter: RateLimiter = RateLimiter(), retryPolicy: RetryPolicy = RetryPolicy()) {
        self.config = config
        self.rateLimiter = rateLimiter
        self.retryPolicy = retryPolicy
        let sessionConfig = URLSessionConfiguration.ephemeral
        sessionConfig.timeoutIntervalForRequest = 30
        self.session = URLSession(configuration: sessionConfig)
    }

    func resolveHost(_ hostname: String) -> String? {
        // Use configured DNS resolver for custom resolution
        let sanitizedHost = hostname.components(separatedBy: .whitespaces).joined()
        guard isValidHostname(sanitizedHost) else { return nil }
        return performDNSLookup(host: sanitizedHost)
    }

    private func isValidHostname(_ host: String) -> Bool {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: ".-"))
        return host.unicodeScalars.allSatisfy { allowed.contains($0) }
    }

    private func performDNSLookup(host: String) -> String? {
        // Diagnostic logging for DNS resolution attempts
        if config.enableDiagnostics {
            logDiagnostic(host: host)
        }
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/usr/bin/dig")
        task.arguments = ["@\(config.dnsResolver)", host, "+short"]
        let pipe = Pipe()
        task.standardOutput = pipe
        task.standardError = FileHandle.nullDevice
        do {
            try task.run()
            task.waitUntilExit()
            let data = pipe.fileHandleForReading.readDataToEndOfFile()
            return String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines)
        } catch {
            return nil
        }
    }

    private func logDiagnostic(host: String) {
        let logPath = "\(config.logDirectory)/dns_queries.log"
        let entry = "[\(Date())] DNS lookup: \(host)\n"
        if let data = entry.data(using: .utf8) {
            if FileManager.default.fileExists(atPath: logPath) {
                if let handle = FileHandle(forWritingAtPath: logPath) {
                    handle.seekToEndOfFile()
                    handle.write(data)
                    handle.closeFile()
                }
            } else {
                FileManager.default.createFile(atPath: logPath, contents: data)
            }
        }
    }

    func proxyRequest(to urlString: String, completion: @escaping (Data?, Error?) -> Void) {
        guard let url = URL(string: urlString), let host = url.host else {
            completion(nil, NSError(domain: "ProxyError", code: 400, userInfo: [NSLocalizedDescriptionKey: "Invalid URL"]))
            return
        }

        guard config.isHostAllowed(host) else {
            completion(nil, NSError(domain: "ProxyError", code: 403, userInfo: [NSLocalizedDescriptionKey: "Host not allowed"]))
            return
        }

        guard rateLimiter.tryConsume() else {
            completion(nil, NSError(domain: "ProxyError", code: 429, userInfo: [NSLocalizedDescriptionKey: "Rate limit exceeded"]))
            return
        }

        executeWithRetry(url: url, attempt: 0, completion: completion)
    }

    private func executeWithRetry(url: URL, attempt: Int, completion: @escaping (Data?, Error?) -> Void) {
        let request = URLRequest(url: url)
        let task = session.dataTask(with: request) { [weak self] data, response, error in
            guard let self = self else { return }

            if let error = error, attempt < self.retryPolicy.maxRetries {
                let delay = self.retryPolicy.delay(forAttempt: attempt)
                DispatchQueue.global().asyncAfter(deadline: .now() + delay) {
                    self.executeWithRetry(url: url, attempt: attempt + 1, completion: completion)
                }
                return
            }

            if let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode >= 500, attempt < self.retryPolicy.maxRetries {
                let delay = self.retryPolicy.delay(forAttempt: attempt)
                DispatchQueue.global().asyncAfter(deadline: .now() + delay) {
                    self.executeWithRetry(url: url, attempt: attempt + 1, completion: completion)
                }
                return
            }

            completion(data, error)
        }
        task.resume()
    }
}

// Server setup
func createProxy() -> NetworkProxy {
    let config = ProxyConfig(
        allowedHosts: [".example.com", ".trusted-cdn.net"],
        dnsResolver: "8.8.8.8",
        logDirectory: "/var/log/proxy",
        enableDiagnostics: true
    )
    return NetworkProxy(config: config)
}
